<?php declare(strict_types=1);namespace StudPulse\Http;use StudPulse\Database\DB;use StudPulse\Domain\{GroupRating,UserAvatar};use StudPulse\Security\{Auth,RateLimit};final class AvatarController{public function upload(Auth$auth):array{$auth->browserOnly();RateLimit::check('avatar:'.$auth->user['id'],8,600);$file=$_FILES['file']??[];$path=$file['tmp_name']??null;if(!is_string($path)||($file['error']??null)!==UPLOAD_ERR_OK||!is_uploaded_file($path)){throw new ApiError(422,'AVATAR_UPLOAD','Не удалось принять фото. Выберите файл ещё раз.');}if(filesize($path)>UserAvatar::MAX_BYTES)throw new ApiError(413,'AVATAR_SIZE','Подготовленное фото превышает 512 КиБ.');$jpeg=file_get_contents($path,false,null,0,UserAvatar::MAX_BYTES+1);if($jpeg===false)throw new ApiError(422,'AVATAR_UPLOAD','Не удалось прочитать фото.');return['version'=>UserAvatar::save($auth->user['id'],$jpeg)];}public function download(Auth$auth,string$id):never{$auth->browserOnly();$id=strtolower($id);if(!UserAvatar::version($id)||($id!==$auth->user['id']&&!GroupRating::mayView($auth->user['id'],$id))){throw new ApiError(404,'AVATAR_NOT_FOUND','Фото недоступно.');}$image=DB::one("SELECT p.avatar_jpeg FROM user_profiles p JOIN users u ON u.id=p.user_id
            WHERE p.user_id=? AND u.status='active'",[$id])['avatar_jpeg']??null;if(!$image)throw new ApiError(404,'AVATAR_NOT_FOUND','Фото недоступно.');header('Cache-Control: private, no-store');header("Content-Security-Policy: sandbox; default-src 'none'");header('Content-Type: image/jpeg');header('Content-Length: '.strlen($image));echo$image;exit;}public function remove(Auth$auth):array{$auth->browserOnly();UserAvatar::erase($auth->user['id']);return['removed'=>true];}}